import {chromium} from 'playwright';import fs from 'fs';
const BASE='http://127.0.0.1:8139/';fs.mkdirSync('prop-refinement-renders',{recursive:true});
const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:390,height:844}});const page=await ctx.newPage();const errors=[];
page.on('pageerror',e=>errors.push('page:'+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('console:'+m.text())});page.on('requestfailed',r=>{const u=r.url(),e=r.failure()?.errorText||'';if(/\.(?:mp3|wav|ogg|m4a)($|\?)/.test(u)&&/ERR_ABORTED/.test(e))return;errors.push('request:'+u+':'+e)});
const ok=(c,m)=>{if(!c)throw new Error(m)};const intersect=(a,b)=>Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left))*Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));
await page.goto(BASE,{waitUntil:'domcontentloaded'});const reps=[1,51,101,151,201,251,301,351],states=[];
for(let i=0;i<reps.length;i++){const L=reps[i];await page.evaluate(L=>startLevel(L),L);await page.waitForTimeout(120);if(await page.locator('#storyCardOverlay.show').count())await page.click('#storyCardContinue');await page.waitForTimeout(80);const s=await page.evaluate(()=>{const rect=o=>{const r=o.getBoundingClientRect();return {left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height}};const board=rect(document.getElementById('board'));const props=[...document.querySelectorAll('.level-prop')].map(x=>({cls:x.className,rect:rect(x),bg:getComputedStyle(x).backgroundColor,pointer:getComputedStyle(x).pointerEvents,opacity:getComputedStyle(x).opacity}));return{board,props,scrollW:document.documentElement.scrollWidth,innerW:window.innerWidth,theme:document.getElementById('app').className,propNames:document.getElementById('levelProps').dataset.props};});ok(s.props.length>=2,`L${L} missing prop medallions`);ok(s.scrollW<=s.innerW+1,`L${L} overflow`);for(const [n,p] of s.props.slice(0,2).entries()){ok(p.rect.left>=0&&p.rect.right<=391&&p.rect.top>=0&&p.rect.bottom<=845,`L${L} prop ${n+1} clipped`);ok(intersect(p.rect,s.board)<10,`L${L} prop ${n+1} overlaps board`);ok(p.pointer==='none',`L${L} prop ${n+1} intercepts pointer input`);ok(p.bg!=='rgba(0, 0, 0, 0)',`L${L} prop ${n+1} has no medallion background`)}states.push({L,theme:s.theme,propNames:s.propNames,board:s.board,props:s.props});await page.screenshot({path:`prop-refinement-renders/chapter-${i+1}-props.png`,fullPage:true})}
ok(new Set(states.map(x=>x.propNames)).size>=6,'Prop sets not varied enough');ok(errors.length===0,'Browser errors: '+errors.join(' | '));console.log('LEVEL_PROP_REFINEMENT_OK',JSON.stringify(states.map(x=>({L:x.L,props:x.propNames,positions:x.props.map(p=>p.rect)}))));await browser.close();
